    expect(w1Drive1.nextCalls).toBe(1)
    expect(w1Drive2.decision.kind).toBe('allow')
    expect(w1Drive2.nextCalls).toBe(1)
    // The resolver's cwd tracks the EXPLICIT agent's live header,
