/**
 * T12 lane A — the in-chain bridge for the REAL live-agent glue bundle.
 *
 * Why this exists: `packages/runtime/src/plugin/live/agent-bindings.mjs`
 * has module-scope `@deepseek-ai/*` imports that are unresolvable in the
 * plain-node runner process (the worktree node_modules carries no such
 * scope; the precedent p8s7r2-residency-resuming.test.ts documents exactly
 * this). The T12 lane A acceptance criteria require assertions at the
 * ACTUAL agents.create / consumption / drain boundaries, so this bridge
 * loads the real glue in-chain with test doubles for the DSH services.
 *
 * Self-provisioning: importing this module idempotently creates
 * `node_modules/@deepseek-ai/{dsh-agent,dsh-session,dsh-llm,dsh-mcp-client}`
 * junction links in the worktree, pointing at the prebuilt DSH test-use
 * workspace packages (tests/deepseek-harness-test-use — the pristine
 * upstream test instance per docs/TEST_METHODS.md). `node_modules/` is
 * gitignored: this is local environment provisioning, NOT a repository
 * change. Transitive imports inside those packages resolve from the DSH
 * checkout's own pnpm layout; only the four top-level bare specifiers of
 * the glue need the worktree links.
 *
 * Reproduction on a fresh checkout (one-liner, run from the worktree root):
 *   node --input-type=module -e "await import('./packages/runtime/test/t12a-live-bridge.mjs')"
 *
 * The doubles mirror ONLY the service surface the glue consumes:
 *   agents               create({sessionId, meta, setup}) / resume({resumeSessionId, setup})
 *                        -> { agent, dispose() }; the setup callback runs
 *                        with the agent-scoped ctx before the handle
 *                        settles (the real DSH semantics the glue relies on).
 *                        alpha.2 (A6): the agent ctx double ALSO carries a
 *                        fake upstream `fs` seam (ctx.fs.resolve — the
 *                        permission adapter's resolveTarget basis) and an
 *                        `agent` back-reference with `session.header.cwd`
 *                        (the lazy FACT 3b cwd read basis) — behavior-inert
 *                        for the alpha.1 worlds (they never read them).
 *                        A2C-2 (alpha.2, plan §7): the handle factory MINTS
 *                        each agent's scope exactly as the real Agent's
 *                        constructor does (`createScope(loopCtx, this)` —
 *                        the public @deepseek-ai/dsh-scope seam), so the
 *                        setup callback's agent ctx ALWAYS carries the
 *                        scope tag (`scopeOf` !== undefined) — the
 *                        Permission Coverage Gate's fail-closed surface
 *                        read (`tools.schemas(scopeOf(agentCtx))`)
 *                        requires it. The scope's backing plugin rides
 *                        ctx.plugin unrecorded (scope plumbing, not a
 *                        world mount — the `plugins` array still counts
 *                        world mounts only, as every assertion assumes).
 *                        The double's tools object carries the public
 *                        `schemas(scope?)` surface seam (registered tools
 *                        minus the accumulated restrict deny — see the
 *                        seam's inline comment).
 *   sessionPersistence   ensureMaterialized(session)
 *   domain               repositories.memberInstances.list / overrides.list
 *                        + the REAL durable-consumption resolvers from
 *                        packages/runtime/agent-setup (model + capability)
 *   subagents            (optional) the SubagentRuntime surface used by
 *                        drainDescendants (drainContinuableDescendants,
 *                        listDescendants)
 */
import { existsSync, lstatSync, mkdirSync, readdirSync, rmSync, symlinkSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
// BP-F (issue #2 blueprint-loading, plan §11.1): the bridge's default
// per-Team resolver strong-parses the world's blueprint sources (the
// domain facade — the runner's .js -> .ts sibling hook applies).
import { parseBlueprint } from '../../domain/blueprint/src/index.js'
import { TEST_USE_REL } from '../../tests/paths.mjs'
// A2C-2 (alpha.2, plan §7): the public scope-mint seam — makeHandle mints
// each handle's agent scope exactly as the real Agent's constructor does
// (the Permission Coverage Gate's fail-closed surface read requires the
// scope tag on the setup ctx). Same package the glue already imports
// (scopeOf) — a public root export, an established seam in this repo.
import { createScope } from '@deepseek-ai/dsh-scope'

const TEST_DIR = dirname(fileURLToPath(import.meta.url))
/** The worktree root (test -> runtime -> packages -> root). */
export const WORKTREE_ROOT = resolve(TEST_DIR, '..', '..', '..')
/** The repository root (the worktree lives under <repo>/.worktrees/). */
const REPO_ROOT = resolve(WORKTREE_ROOT, '..', '..')
/** The pristine upstream DSH test-use checkout (docs/TEST_METHODS.md). */
const DSH_TEST_USE = resolve(REPO_ROOT, TEST_USE_REL)

/** The four top-level @deepseek-ai/* specifiers of the real glue. */
const GLUE_PACKAGE_LINKS = [
  ['dsh-agent', ['packages', 'core', 'agent']],
  ['dsh-session', ['packages', 'core', 'session']],
  ['dsh-llm', ['packages', 'llm', 'llm']],
  ['dsh-mcp-client', ['packages', 'mcp', 'mcp-client']],
]

function entryExists(p) {
  try {
    lstatSync(p)
    return true
  } catch {
    return false
  }
}

/**
 * Idempotently provision the four top-level @deepseek-ai/* specifiers as
 * junction links under the worktree node_modules (local env only —
 * gitignored).
 */
export function ensureGlueResolvable() {
  const scopeDir = join(WORKTREE_ROOT, 'node_modules', '@deepseek-ai')
  for (const [name, parts] of GLUE_PACKAGE_LINKS) {
    const linkPath = join(scopeDir, name)
    if (entryExists(linkPath)) continue
    const target = join(DSH_TEST_USE, ...parts)
    if (!existsSync(join(target, 'package.json'))) {
      throw new Error(`t12a-live-bridge: the DSH test-use package dir is missing: ${target}`)
    }
    mkdirSync(scopeDir, { recursive: true })
    symlinkSync(target, linkPath, 'junction')
  }
}

let glueModulePromise
/** Import the real glue module (provisions the links first; cached). The
 *  relative string specifier keeps the runner's `.js -> .ts` sibling hook
 *  applicable (a URL object would arrive pre-resolved and bypass it). */
export async function loadGlueModule() {
  ensureGlueResolvable()
  if (glueModulePromise === undefined) {
    glueModulePromise = import('../src/plugin/live/agent-bindings.mjs')
  }
  return glueModulePromise
}

/**
 * alpha.2 (A6): the fake upstream `fs` seam for the permission adapter's
 * `resolveTarget` closure (`ctx.fs.resolve(path, { cwd })`). Deterministic
 * and PURE (no fs access): an absolute path (POSIX `/` or Windows `\`)
 * resolves as-is; a relative path joins onto the passed cwd (the FACT 3b
 * lazy-read basis the glue threads from `agent.session.header.cwd`).
 * `..` segments collapse deterministically (no fs). Every call is recorded
 * (`calls: [{ path, cwd? }]`) so a test can assert the exact cwd the glue
 * threaded at RESOLVE time. `targetKey` is a plain `file://`-prefixed
 * string standing in for the branded FsTargetKey (the glue unbrands with
 * String()).
 *
 * RC2-A1 (rc2-repair plan §12 tightening + A1-T1): the fake ALSO carries
 * the upstream `contains` containment seam — the rc.2 tightening refuses
 * exact/subtree file permissions on a provider without it, so every
 * glue-level permission world (a6a / bp1, exact + subtree rules) needs
 * the FULL seam. PURE upstream fs-local semantics over the normalized
 * keys (no fs): `contains(parent, child)` is true iff the child key is
 * EQUAL to the parent key or strictly below it — no `..` escape, no
 * sibling prefix match (`/team` is NOT a parent of `/teambar`). The
 * adapter passes RESOLVED targets (this fake's own resolve output), so
 * the keys are already canonical; a raw string key is tolerated for
 * direct test use. Every call is recorded in `containsCalls`.
 * @returns {{calls: Array<{path: string, cwd: string | undefined}>, containsCalls: Array<{parent: unknown, child: unknown}>, resolve: (path: string, opts?: {cwd?: string}) => Promise<{targetKey: string, displayPath: string}>, contains: (parent: unknown, child: unknown) => boolean}}
 */
function makeFakeFs() {
  const calls = []
  const containsCalls = []
  function normalize(cwd) {
    return String(cwd).replace(/\\/g, '/').replace(/\/+$/, '')
  }
  function targetOf(path, cwd) {
    const p = String(path).replace(/\\/g, '/')
    let joined
    if (p.startsWith('/')) {
      joined = p
    } else if (typeof cwd === 'string' && cwd !== '') {
      joined = normalize(cwd) + '/' + p
    } else {
      joined = '/' + p
    }
    const out = []
    for (const s of joined.split('/')) {
      if (s === '' || s === '.') continue
      if (s === '..') out.pop()
      else out.push(s)
    }
    const key = '/' + out.join('/')
    return { targetKey: `file://${key}`, displayPath: key }
  }
  function keyOf(target) {
    const raw = typeof target === 'string' ? target : String(target?.targetKey ?? '')
    return raw.startsWith('file://') ? raw.slice('file://'.length) : raw
  }
  return {
    calls,
    containsCalls,
    async resolve(path, opts = {}) {
      calls.push({
        path: String(path),
        cwd: opts.cwd === undefined ? undefined : String(opts.cwd),
      })
      return targetOf(path, opts.cwd)
    },
    contains(parent, child) {
      containsCalls.push({ parent, child })
      const pk = keyOf(parent)
      const ck = keyOf(child)
      return ck === pk || ck.startsWith(`${pk}/`)
    },
  }
}

/**
 * One agent-scoped ctx double: records every `on(event, listener)`
 * registration (with a working disposer), every plugin() fiber (a thenable
 * that resolves immediately, with a recording .dispose()), the tools
 * register/execute surface the glue uses, and — T12-M2 — the DSH
 * systemPrompt builtin double (agent-scoped sections that shadow
 * same-named globals; duplicate scoped names in one agent scope throw;
 * assemble() composes the prompt layer the assertions read).
 *
 * alpha.2 (A6): the double ALSO carries the fake upstream `fs` seam
 * (`ctx.fs.resolve`) — the permission adapter's `resolveTarget` closure
 * basis (absent from the alpha.1 worlds: they never read it, so the
 * addition is behavior-inert for them) and the `agent` back-reference
 * (set by createAgentsDouble's handle factory — the `ctx.agent` DX
 * accessor basis the glue's lazy `session.header.cwd` read uses).
 *
 * H1 (alpha.2 hardening, P0): the double ALSO carries the `tools.guard`
 * seam (the monotonic end-cap guard registration) — the permission
 * adapter's install is fail-closed on its absence
 * (`alpha2-permission-guard-unavailable`), so every permission world's
 * ctx double must record the guard with a working disposer.
 *
 * A2C-2 (alpha.2, plan §7): the double ALSO carries the `tools.schemas`
 * seam (the public model-facing surface enumeration) — the Permission
 * Coverage Gate's fail-closed surface read
 * (`alpha2-permission-coverage-surface-unavailable`) requires it. The
 * double's flat-layer semantics: one entry per tool registered through
 * the double's own `tools.register`, minus the accumulated
 * `tools.restrict({ deny })` union (see the seam's inline comment for
 * the flat approximation of the real inherited-layer mask).
 *
 * @param {Array<{name: string, order: number, text: string}>} [globalSections]
 *   the world's global prompt layer (one shared array per world).
 * @param {Record<string, string>} [mcpFailures]
 *   multi-mcp (Task C, plan §6.7): per-server MCP activation FAILURE
 *   injection — when a recorded (non-scope-plumbing) plugin fiber's
 *   `options.serverName` has an entry here, the fiber REJECTS on await
 *   with `new Error(<message>)` (the bridge's only activation-failure
 *   seam; the real mcpClient fiber rejects with the server's startup
 *   error). Absent/empty = every fiber settles as before.
 * @param {Record<string, string[]>} [mcpToolNames]
 *   multi-mcp (Task C, plan §6.11): per-server MCP tool names — when a
 *   recorded plugin fiber ACTIVATES (its first successful settle), the
 *   listed tool names are registered on THIS ctx through the same
 *   `tools.register` path a real mcpClient fiber's tools use (the
 *   Permission Coverage Gate's PROVEN-mount delta basis, plan §7.3-C);
 *   dispose() unregisters them (the real fiber's teardown removes its
 *   tools). Absent/empty = no registration (the pre-multi-mcp behavior).
 */
function makeAgentCtx(globalSections, mcpFailures, mcpToolNames) {
  const listeners = []
  const registeredTools = []
  const toolExecutions = []
  const plugins = []
  const scopedSections = []
  // alpha.1: the agent-scoped restriction seam (tools.restrict({ deny })) —
  // records every restriction call on THIS ctx (sibling-inert by
  // construction: each ctx double is one agent scope); the scoped deny
  // list is the union of all restrict calls (the public seam accumulates).
  const toolRestrictions = []
  // H1 (alpha.2 hardening, P0): the monotonic end-cap guard seam
  // (tools.guard) — records every guard registration on THIS ctx with a
  // working disposer (the adapter's composite disposer removes the
  // listener FIRST and the guard LAST).
  const toolGuards = []
  // P0-3 (hardening §5): the unified operation-order log — records the
  // SEQUENCE of tools.register / tools.restrict calls on THIS ctx so a test
  // can verify the frozen setup ordering (builtin deny BEFORE the team tool
  // registrations). Each entry is { op, toolName? }.
  const opLog = []
  // alpha.1: the skill registration seam (agent.ctx.get('skills').register)
  // — records every scoped skill registration on THIS ctx with a working
  // disposer (the agent-scope unwind removes them, as with tools).
  const registeredSkills = []
  // fix/alpha2-explicit-agent-setup-compat: the scope argument of every
  // `tools.schemas(scope)` call, in order (the real seam takes the scope
  // key — the Agent; the double accepts it for signature fidelity and now
  // RECORDS it so a test can pin WHICH identity the Permission Coverage
  // Gate enumerated the surface through).
  const schemaScopeArgs = []
  const systemPrompt = {
    globals: globalSections,
    section(spec) {
      if (spec === null || typeof spec !== 'object' || typeof spec.name !== 'string' || spec.name === '') {
        throw new TypeError('systemPrompt.section: spec.name (non-empty string) is required')
      }
      if (typeof spec.order !== 'number' || !Number.isFinite(spec.order)) {
        throw new TypeError('systemPrompt.section: spec.order must be a finite number')
      }
      const existing = scopedSections.find((entry) => !entry.disposed && entry.name === spec.name)
      if (existing !== undefined) {
        throw new Error(`systemPrompt.section: duplicate scoped section name '${spec.name}' in one agent scope`)
      }
      const entry = {
        name: spec.name,
        order: spec.order,
        text: typeof spec.text === 'function' ? spec.text({}) : String(spec.text ?? ''),
        scope: 'scoped',
        disposed: false,
      }
      scopedSections.push(entry)
      return () => {
        entry.disposed = true
      }
    },
    assemble() {
      const activeScoped = scopedSections.filter((entry) => !entry.disposed)
      return globalSections
        .filter((section) => !activeScoped.some((entry) => entry.name === section.name))
        .map((section) => ({ ...section, scope: 'global' }))
        .concat(activeScoped.map((entry) => ({ ...entry, scope: 'scoped' })))
        .sort((a, b) => a.order - b.order || (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))
    },
  }
  // alpha.2 (A6): the fake upstream fs seam (the permission adapter's
  // resolveTarget closure basis; see makeFakeFs).
  const fs = makeFakeFs()
  return {
    listeners,
    registeredTools,
    toolExecutions,
    plugins,
    systemPrompt,
    toolRestrictions,
    toolGuards,
    opLog,
    registeredSkills,
    schemaScopeArgs,
    fs,
    // alpha.2 (A6): the agent back-reference — the handle factory sets it
    // to the live agent (the `ctx.agent` DX accessor basis; undefined
    // between construction and the handle wiring, as on a real context
    // outside an initiator boundary).
    agent: undefined,
    on(event, listener) {
      const entry = { event, listener, active: true }
      listeners.push(entry)
      return () => {
        entry.active = false
      }
    },
    get(key) {
      if (key === 'skills') {
        return {
          // The SkillRegistrationDisposer contract (T3 skill-adapter) is an
          // OBJECT with a dispose() method — the adapter calls `d.dispose()`,
          // so returning a bare function would throw (swallowed) and the
          // registration would never be unwound.
          register(def) {
            const entry = { def, disposed: false }
            registeredSkills.push(entry)
            return {
              dispose() {
                entry.disposed = true
              },
            }
          },
        }
      }
      return undefined
    },
    plugin(pluginSpec, options) {
      // A2C-2 (alpha.2, plan §7): the dsh-scope package's `createScope`
      // mints a scope through this seam with its PRIVATE no-op FUNCTION
      // backing plugin and reads the fiber's `.ctx` carrier (the double
      // stands in for cordis's `fiber.ctx.extend` — prototype
      // inheritance, mirroring cordis's extend()). A function-spec call
      // is scope plumbing, NOT a world mount: it is NOT recorded in
      // `plugins` (every assertion on that array targets world mounts —
      // the mini-MCP fibers — e.g. H1-3's zero-mount pin and t4a's
      // mcpMounts / mcpAllDisposed). The world's own plugin calls
      // (non-function specs: the MCP client with its options) record
      // exactly as before.
      const isScopePlumbing = typeof pluginSpec === 'function'
      // multi-mcp (Task C): the ctx this fiber was minted on (the fiber's
      // own methods run with `this` = the fiber, so the tools registration
      // path is captured here).
      const ctxSelf = this
      // multi-mcp (Task C): per-server activation behavior, computed for
      // the recorded (world-mount) fibers only — scope-plumbing fibers
      // keep the pre-multi-mcp settle exactly.
      const serverName =
        typeof options?.serverName === 'string' ? options.serverName : undefined
      const failMessage =
        !isScopePlumbing &&
        serverName !== undefined &&
        mcpFailures !== null &&
        typeof mcpFailures === 'object'
          ? mcpFailures[serverName]
          : undefined
      const activationError =
        failMessage === undefined ? undefined : new Error(failMessage)
      const toolNamesForServer =
        !isScopePlumbing &&
        serverName !== undefined &&
        mcpToolNames !== null &&
        typeof mcpToolNames === 'object'
          ? mcpToolNames[serverName] ?? []
          : []
      let activated = false
      const activationDisposers = []
      const fiber = {
        pluginSpec,
        options,
        disposed: false,
        // multi-mcp (Task C, plan §6.10): dispose-call counter — the
        // "disposed exactly once" pin (a real fiber disposed twice is a
        // lifecycle bug the glue must never produce).
        disposeCount: 0,
        // A2C-2: the scope carrier — `createScope` does
        // `fiber.ctx.extend({ [kScope]: key })`; the tag lands on the
        // extended object and `scopeOf(agentCtx)` walks THIS prototype
        // chain to read it (carrier -> this ctx -> ...).
        ctx: Object.assign(Object.create(this), {
          extend(props) {
            const child = Object.create(this)
            // Reflect.ownKeys (NOT Object.entries): cordis's extend carries
            // symbol-keyed own properties too — the dsh-scope tag itself is
            // a symbol ([kScope]), and dropping it would leave the scoped
            // ctx untagged (scopeOf === undefined).
            for (const k of Reflect.ownKeys(props)) child[k] = props[k]
            return child
          },
        }),
        dispose() {
          this.disposed = true
          this.disposeCount += 1
          // multi-mcp (Task C): the real fiber's teardown removes the
          // server's tools from the agent scope.
          for (const dispose of activationDisposers) dispose()
        },
        // `await fiber` (the glue's MCP-activation await) must settle exactly
        // once. The settled value is a NON-thenable (`undefined`): resolving
        // the adoption promise with `fiber` itself would re-enter this `then`
        // forever (fiber IS a thenable — `Promise.resolve(fiber)` / the
        // adoption's `resolve(fiber)` re-adopts it). The glue uses the `fiber`
        // variable (not the resolved value) for `state.mcpFiber`, so settling
        // to `undefined` is behavior-preserving.
        // multi-mcp (Task C, plan §6.7): a fiber with an injected failure
        // REJECTS on await (the real mcpClient fiber's failOnStartupError
        // rejection) — the message is the world's configured one.
        then(onfulfilled, onrejected) {
          if (activationError !== undefined) {
            return Promise.reject(activationError).then(onfulfilled, onrejected)
          }
          // multi-mcp (Task C, plan §6.11): the MCP mount's tool
          // registration at activation (the real mcpClient fiber registers
          // its server's tools on the agent scope as part of activation) —
          // idempotent (a real Promise settles once; a double settle must
          // not double-register), riding the SAME tools.register path so
          // the opLog / surface reads see the mount's tools.
          if (!activated && toolNamesForServer.length > 0) {
            activated = true
            for (const name of toolNamesForServer) {
              const dispose = ctxSelf.tools.register({
                name,
                description: `mcp tool of server ${serverName}`,
              })
              activationDisposers.push(dispose)
            }
          }
          return Promise.resolve().then(() => (onfulfilled ? onfulfilled(undefined) : undefined))
        },
        catch(onrejected) {
          if (activationError !== undefined) {
            return Promise.reject(activationError).catch(onrejected)
          }
          return Promise.resolve().then(() => (onrejected ? onrejected(undefined) : undefined))
        },
      }
      if (!isScopePlumbing) plugins.push(fiber)
      return fiber
    },
    tools: {
      register(def) {
        registeredTools.push(def)
        opLog.push({ op: 'register', toolName: String(def?.name ?? '') })
        return () => {
          const i = registeredTools.indexOf(def)
          if (i !== -1) registeredTools.splice(i, 1)
        }
      },
      execute(call) {
        toolExecutions.push(call)
        return Promise.resolve({ ok: true, callId: call.callId })
      },
      // alpha.1: the public Agent-scoped restriction seam (tools.restrict).
      // Records the deny list on THIS ctx only (sibling-inert); the scoped
      // effective deny is the union of every call (the seam accumulates).
      // P0-2 (hardening §4): the real seam returns the exact disposer that
      // lifts this restriction; the double returns a no-op disposer (the
      // toolRestrictions union is the effective deny; the double does not
      // model the lift) so the adapter's captured-disposer close path works.
      restrict(opts) {
        toolRestrictions.push(opts)
        opLog.push({ op: 'restrict', toolName: (opts?.deny ?? []).join(',') })
        return () => {}
      },
      // H1 (alpha.2 hardening, P0): the monotonic end-cap guard seam —
      // the real upstream `tools.guard` registers an agent-scoped
      // monotonic veto after the extensible tools/pre-execute waterfall
      // and returns the exact disposer; the double records the guard
      // function on THIS ctx (sibling-inert) with the same disposer
      // semantics (the adapter's composite disposer rides the SAME
      // toolDisposers slot as the listener — one entry removes both).
      guard(fn) {
        if (typeof fn !== 'function') {
          throw new TypeError('tools.guard: guard (function) is required')
        }
        const entry = { fn, active: true }
        toolGuards.push(entry)
        opLog.push({ op: 'guard' })
        return () => {
          entry.active = false
        }
      },
      // A2C-2 (alpha.2, plan §7): the public model-facing surface seam
      // (`tools.schemas(scope)`) — the Permission Coverage Gate
      // (agent-bindings.mjs) enumerates the FINAL surface through it.
      // Established double-extension pattern (alpha.1 added restrict,
      // H1 added guard): the product grew a public seam, the double
      // records it. Flat-double semantics: one entry per tool registered
      // through THIS double's `tools.register` (the CURRENT set — the
      // register disposer's unwind removes it, as on a real scope
      // unwind) minus every name denied by any `tools.restrict({ deny })`
      // recorded on THIS ctx (the public seam accumulates). The real
      // seam's agent-scoped view is `inherited (restricted) + own`;
      // the double has ONE flat layer, so the deny mask applies to the
      // whole list — the flat approximation of the real inherited-layer
      // mask. No repo world observes the divergence: the double worlds'
      // preset double mount registers no base/preset tools (the double's
      // own registrations are the scope-own team tools, which the real
      // seam exempts from restrict, and no repo deny list names a team
      // tool). The `scope` argument is accepted for signature fidelity
      // (the double is one scope) and RECORDED (schemaScopeArgs): a test
      // can pin the exact identity the gate enumerated through (the
      // fix/alpha2-explicit-agent-setup-compat precedence legs).
      // Deterministic: sorted by name, stable
      // `{ name, description }` shape (the gate consumes names; the real
      // upstream returns ToolSchema[] deep clones — description mirrors
      // the registered def's or '').
      schemas(scope) {
        schemaScopeArgs.push(scope)
        const denied = new Set()
        for (const opts of toolRestrictions) {
          for (const name of opts?.deny ?? []) denied.add(String(name))
        }
        return registeredTools
          .filter(
            (def) =>
              def !== null &&
              typeof def === 'object' &&
              typeof def.name === 'string' &&
              !denied.has(def.name),
          )
          .map((def) => ({
            name: def.name,
            description: typeof def.description === 'string' ? def.description : '',
          }))
          .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))
      },
    },
  }
}

/**
 * The agents service double (the DSH agents create/resume seam). Records
 * every create/resume request (sessionId + meta + setup presence) and
 * every dispose/followup/cancel. `create`/`resume` run the provided setup
 * callback with the agent-scoped ctx and settle only after it completes —
 * the real DSH handle semantics the glue relies on.
 *
 * @param {object} [options]
 * @param {(agent: object) => Promise<void>} [options.whenIdleBehavior]
 *   the per-agent whenIdle() behavior (default: resolves immediately).
 * @param {(req: { resumeSessionId: string; setup?: unknown }) => Promise<void>} [options.resumeGate]
 *   work-completion wake-up (teardown gate regression, G8): a per-resume
 *   SUSPENSION point — awaited (after the resume request is recorded,
 *   before the handle is built) so a test can interleave `close()` while
 *   an `agents.resume()` is in flight (the real handle can outlive the
 *   close snapshot only if the glue never re-checks its lifecycle). The
 *   request carries the RAW resume args — `setup` distinguishes a Team
 *   glue resume (a wrapped AgentSetup is present) from a foreign raw
 *   resume (S1 G7–G10 gate on it). Absent = resume settles immediately
 *   (the pre-G8 double behavior).
 * @param {Array<{name: string, order: number, text: string}>} [options.systemPromptGlobals]
 *   the world's global prompt layer for every agent ctx (T12-M2; default:
 *   the DSH service pair harness:identity + a global deployment:persona).
 * @param {Record<string, string>} [options.mcpFailures]
 *   multi-mcp (Task C, plan §6.7): per-server MCP activation failure
 *   injection (see makeAgentCtx' `mcpFailures`), shared by every agent
 *   ctx of this double.
 * @param {Record<string, string[]>} [options.mcpToolNames]
 *   multi-mcp (Task C, plan §6.11): per-server MCP tool names (see
 *   makeAgentCtx' `mcpToolNames`), shared by every agent ctx of this
 *   double.
 * @param {boolean} [options.passExplicitAgent]
 *   fix/alpha2-explicit-agent-setup-compat (default false): the DSH
 *   0.1.5+ AgentSetup contract — the setup callback is invoked as
 *   `setup(agentCtx, agent)` (the factory passes the composed Agent
 *   explicitly as the SECOND parameter). Default: the 0.1.2-era
 *   one-argument call `setup(agentCtx)`.
 * @param {boolean} [options.legacyCtxAgent]
 *   fix/alpha2-explicit-agent-setup-compat (default true): the 0.1.2-era
 *   `ctx.agent` reverse association (the agent back-reference on the
 *   setup ctx). DSH 0.1.5 REMOVED it — pass `false` to model the 0.1.5
 *   world (the setup ctx then carries NO identity at all beyond the
 *   explicit argument / scope tag).
 * @param {boolean} [options.mintScope]
 *   fix/alpha2-explicit-agent-setup-compat (default true): mint each
 *   agent's scope (the public `createScope` seam) so
 *   `scopeOf(agentCtx)` is defined on the setup ctx. Pass `false` to
 *   model a setup ctx whose scope tag the plugin CANNOT read (the real
 *   0.1.5 shape across duplicate @deepseek-ai/dsh-scope package
 *   instances — the module-private Symbol tag is unreadable from a
 *   second package instance).
 * @param {(agent: object) => { ctxAgent?: object, scopeKey?: object }} [options.identityOverride]
 *   fix/alpha2-explicit-agent-setup-compat: per-handle identity control
 *   (the precedence legs): `ctxAgent` replaces the value the `ctx.agent`
 *   back-reference points at (instead of the handle's own agent), and
 *   `scopeKey` replaces the scope-mint key (instead of the handle's own
 *   agent) — letting one world pin THREE distinct identities (explicit
 *   Agent vs `ctx.agent` vs `scopeOf(agentCtx)`).
 */
export function createAgentsDouble(options = {}) {
  const creates = []
  const resumes = []
  const disposals = []
  const followups = []
  const steers = []
  const injects = []
  const cancels = []
  const handles = new Map()
  const whenIdleBehavior = options.whenIdleBehavior ?? (() => Promise.resolve())
  // work-completion wake-up (G8): the per-resume suspension point (absent =
  // resume settles immediately, the pre-G8 double behavior).
  const resumeGate = options.resumeGate
  // multi-mcp (Task C): the per-server activation behavior tables (shared
  // by every agent ctx; absent = the pre-multi-mcp double behavior).
  const mcpFailures = options.mcpFailures
  const mcpToolNames = options.mcpToolNames
  // fix/alpha2-explicit-agent-setup-compat: the AgentSetup contract knobs
  // (defaults reproduce the 0.1.2-era world every pre-existing test pins).
  const passExplicitAgent = options.passExplicitAgent === true
  const legacyCtxAgent = options.legacyCtxAgent !== false
  const mintScope = options.mintScope !== false
  const identityOverride = options.identityOverride
  // C1 (restart-recovery, guide §13.3): the fake `agent/created` /
  // `agent/disposed` event hook — fired (awaited) INSIDE create/resume
  // BEFORE the handle is published (the production awaited-serial veto
  // point: a hook rejection rejects the create/resume and the handle is
  // never built — the unpublished agent), and inside handle.dispose()
  // (fire-and-forget upstream — a hook fault never breaks the dispose).
  // Absent = the pre-C1 double behavior (no events at all).
  const activationEvents = options.activationEvents
  // C1 (guide §13.3 G5/G6): per-session RESUME FAULT injection — a
  // (sessionId, callIndex) => error|undefined script; a returned error
  // REJECTS that resume call AFTER it is recorded, BEFORE the agent is
  // created (models the session-layer writer-held rejection: no
  // agent/created fires for a rejected resume). Absent = no faults.
  const resumeFaults = options.resumeFaults
  const resumeCallCounts = new Map()
  // C1 (guide §8.2): the EXACT-GENERATION identity objects the double
  // mints per activation — the same object the created and the matching
  // disposed events carry (the strict-generation key; a test models the
  // upstream AgentLoop rollback by feeding the created event's identity
  // back as the disposed agent). Map: sessionId -> latest identity.
  const agentIdentities = new Map()
  // T12-M2: one shared global prompt layer per world (the DSH service
  // registers harness:identity + a global deployment:persona section at
  // construction; the persona glue's scoped installs shadow that global).
  const globalSections = options.systemPromptGlobals ?? [
    { name: 'harness:identity', order: -1000, text: 'You are an AI agent powered by DeepSeek Harness.' },
    { name: 'deployment:persona', order: 0, text: '' },
  ]

  async function makeHandle(sessionId, { setup, meta }) {
    const ctx = makeAgentCtx(globalSections, mcpFailures, mcpToolNames)
    // alpha.2 (A6): the session header double (the lazy `cwd` read basis of
    // the permission adapter's resolveTarget closure, FACT 3b). CREATE
    // carries the meta.cwd the glue requested (the production session
    // header materializes from exactly that meta); RESUME has no meta —
    // the durable-header analogue is a deterministic per-session fixture
    // workspace (a test may still mutate `header.cwd` to pin the lazy
    // read). Mutable on purpose (the bridge is a plain JS double; the
    // lazy-read test rewrites it between resolve calls).
    const createCwd = meta !== undefined && meta !== null && typeof meta.cwd === 'string' && meta.cwd !== ''
      ? meta.cwd
      : join(WORKTREE_ROOT, 'fixture-ws', sessionId)
    const agent = {
      // S1 (supplement INV-3): the generation identity — the real 0.1.7
      // Agent exposes a top-level `id` (the fence's structural
      // projection reads ONLY `.id`); the fake agent IS the object the
      // created/disposed events carry and the setup receives.
      id: sessionId,
      session: { id: sessionId, header: { cwd: createCwd } },
      // A2C-2: assigned AFTER the scope mint below (the real Agent's
      // constructor order: `this.scope = createScope(loopCtx, this);
      // this.ctx = this.scope.ctx.extend({ agent: this })`).
      ctx: undefined,
      // Work-completion wake-up: the real Agent's `status` is a getter
      // over its phase ('idle' | 'running'); the double models it as a
      // plain MUTABLE property (default 'idle' — a freshly created or
      // resumed agent has no in-flight turn), so a test can pin the
      // busy/idle observation the wake-up primitive branches on.
      status: 'idle',
      followup(message) {
        followups.push({ sessionId, message })
      },
      steer(message) {
        steers.push({ sessionId, message })
      },
      // The DSH rc.2 Agent's `inject` — the NON-WAKING next-step send
      // (`send(input, 'next-step', false)` in agent-loop agent.ts @
      // fb2c4b9e69, vs `steer`'s `send(input, 'next-step', true)`),
      // modeled for faithful recording. The work-completion wake's glue
      // must pick followup (idle) or steer (busy) — inject stays
      // untouched by the glue (pinned to 0 by the glue suite).
      inject(message) {
        injects.push({ sessionId, message })
      },
      whenIdle() {
        return whenIdleBehavior(agent)
      },
      cancel(args) {
        cancels.push({ sessionId, args })
      },
    }
    // A2C-2 (alpha.2, plan §7): mint the agent's SCOPE before the setup
    // callback runs — the real Agent mints it in its constructor, so the
    // setup callback's agent ctx ALWAYS carries the scope tag. The
    // Permission Coverage Gate's surface read is fail-closed on a
    // ctx whose identity the plugin cannot resolve, and a faithful
    // double must not FATAL a world the real harness would never FATAL.
    // The scope's backing plugin (the private no-op in dsh-scope) rides
    // the ctx.plugin seam above — unrecorded (scope plumbing, not a
    // world mount). `createScope(ctx, agent)` mirrors the real scope key
    // (the Agent itself is the opaque routing key).
    // fix/alpha2-explicit-agent-setup-compat: the mint is OPT-IN per world
    // (`mintScope`) and the key is overridable (`identityOverride`) —
    // the 0.1.5-style worlds either drop the tag entirely (a plugin on a
    // second dsh-scope package instance reads `scopeOf(agentCtx) ===
    // undefined` for a perfectly healthy Agent) or pin a distinct key
    // (the precedence legs).
    const identity =
      typeof identityOverride === 'function' ? identityOverride(agent) : {}
    if (mintScope) {
      const scopeKey = identity.scopeKey !== undefined ? identity.scopeKey : agent
      const scope = createScope(ctx, scopeKey)
      agent.ctx = scope.ctx
    } else {
      // No minted scope: the setup ctx is the agent ctx itself (still a
      // fully functional ctx — only the plugin-readable identity tag is
      // absent, exactly the 0.1.5 / duplicate-package-instance shape).
      agent.ctx = ctx
    }
    // alpha.2 (A6): the agent back-reference — the handle factory sets it
    // to the live agent (the 0.1.2-era `ctx.agent` reverse association).
    // fix/alpha2-explicit-agent-setup-compat: the association is OPT-IN
    // per world (`legacyCtxAgent` — DSH 0.1.5 removed it) and overridable
    // (`identityOverride.ctxAgent`) for the three-identity precedence
    // legs.
    const ctxAgent = identity.ctxAgent !== undefined ? identity.ctxAgent : legacyCtxAgent ? agent : undefined
    if (ctxAgent !== undefined) ctx.agent = ctxAgent
    const handle = {
      agent,
      async dispose() {
        disposals.push(sessionId)
        handles.delete(sessionId)
        // C1 (guide §8.2): the fire-and-forget `agent/disposed` event —
        // the exact identity object the matching created event carried
        // (the fence's strict-generation key). A hook fault never breaks
        // the dispose (upstream logs listener errors, it does not
        // propagate them).
        const disposedIdentity = agentIdentities.get(sessionId)
        if (activationEvents !== undefined && disposedIdentity !== undefined) {
          try {
            await activationEvents({
              kind: 'disposed',
              agent: disposedIdentity,
              source: 'resume',
              sessionId,
            })
          } catch {
            // a throwing disposed listener is swallowed (fire-and-forget
            // upstream semantics)
          }
        }
        return undefined
      },
    }
    // S1 (supplement INV-3): the generation identity is registered
    // BEFORE the setup runs — the setup receives THIS object as the
    // explicit Agent and the awaited-serial `agent/created` announcement
    // (fired by the caller AFTER setup, mirroring the 0.1.7 in-host
    // lifecycle `createAgent → setupAndPublish → … → announce`) carries
    // the SAME object: the fence's exact-match claim key.
    agentIdentities.set(sessionId, agent)
    // fix/alpha2-explicit-agent-setup-compat: the DSH 0.1.5+ factory
    // invokes `setup(agentCtx, agent)` — the explicit composed Agent as
    // the SECOND argument (0.1.5-rc.2 agent-loop: `setup?.(
    // prepared.agent.ctx, prepared.agent)`); the 0.1.2-era contract is the
    // one-argument call. The double honors the world's chosen contract.
    if (setup !== undefined) {
      await (passExplicitAgent ? setup(agent.ctx, agent) : setup(agent.ctx))
    }
    // NOTE (S1): the handle is deliberately NOT published here — the
    // caller publishes it AFTER the awaited-serial `agent/created`
    // announcement passes (a vetoed announcement leaves no published
    // handle — the unpublished-agent rollback shape the G-suite's
    // handle-count invariants pin).
    return handle
  }

  return {
    creates,
    resumes,
    disposals,
    followups,
    steers,
    injects,
    cancels,
    handles,
    globalSections,
    agentIdentities,
    async create(req) {
      const sessionId = String(req.sessionId)
      creates.push({ sessionId, meta: req.meta, setupProvided: req.setup !== undefined })
      // C1 (guide §13.3) + S1 (supplement INV-3, 0.1.7 lifecycle
      // verified in-host — Commit-4 defect evidence): setup runs BEFORE
      // the awaited-serial `agent/created` announcement, and the
      // announcement carries the SAME Agent object the setup received
      // (createAgent → setupAndPublish → initializeAgent → runMaintenance
      // → publish → announce). The handle is published ONLY after the
      // announcement passes: a hook rejection rejects this create and no
      // handle is ever published (the unpublished-agent rollback shape).
      const handle = await makeHandle(sessionId, req)
      if (activationEvents !== undefined) {
        await activationEvents({ kind: 'created', agent: agentIdentities.get(sessionId), source: 'startup', sessionId })
      }
      handles.set(sessionId, handle)
      return handle
    },
    async resume(req) {
      const sessionId = String(req.resumeSessionId)
      resumes.push({ sessionId, setupProvided: req.setup !== undefined })
      // G8: suspend AFTER the request is recorded so a test can observe
      // the in-flight resume and interleave close() before it settles.
      if (resumeGate !== undefined) await resumeGate(req)
      // C1 (guide §13.3 G5/G6): the scripted writer-held fault — the
      // session-layer rejection fires AFTER the record, BEFORE any agent
      // exists (no setup, no created event for a rejected resume).
      if (resumeFaults !== undefined) {
        const call = resumeCallCounts.get(sessionId) ?? 0
        resumeCallCounts.set(sessionId, call + 1)
        const fault = resumeFaults(sessionId, call)
        if (fault !== undefined && fault !== null) throw fault
      }
      // C1 (guide §13.3) + S1 (supplement INV-3): setup runs BEFORE the
      // awaited-serial `agent/created` announcement (source 'resume' —
      // the upstream resume announcement; a cold-restart resume is
      // exactly the ordinary SessionController path the fence vetoes
      // when Team-managed), carrying the SAME Agent object; the handle
      // is published only after the announcement passes.
      const handle = await makeHandle(sessionId, req)
      if (activationEvents !== undefined) {
        await activationEvents({ kind: 'created', agent: agentIdentities.get(sessionId), source: 'resume', sessionId })
      }
      handles.set(sessionId, handle)
      return handle
    },
  }
}

/**
 * The sessionPersistence service double (records every materialization).
 *
 * C1 (restart-recovery, guide §5.1/§13.2): the double now ALSO serves
 * `exists(sessionId)` — the glue's durable-existence seam (the production
 * host wrapper's `stat(id) !== undefined`). DEFAULT: the test-world
 * analogue of the upstream `SessionPersistence.stat()` truth — the
 * canonical durable session file under the CURRENT `process.env.DSH_HOME`
 * (the pre-C1 physical probe's semantics, MOVED into the test fixture:
 * the production glue no longer guesses on disk — guide §5. Every
 * pre-existing test that wrote a `writeDurableFixture` under a
 * `withDshHome` home sees the same truth as before, byte-for-byte).
 * A test may OVERRIDE with `options.exists` (a `(sessionId) =>
 * boolean | Promise<boolean>`; a throwing override models the D4 backend
 * fault that must PROPAGATE, never be read as "not durable").
 */
export function createSessionPersistenceDouble(options = {}) {
  const materialized = []
  const existsCalls = []
  const exists = options.exists
  return {
    materialized,
    existsCalls,
    ensureMaterialized(session) {
      materialized.push(String(session.id))
      return Promise.resolve()
    },
    exists(sessionId) {
      const sid = String(sessionId)
      existsCalls.push(sid)
      if (typeof exists === 'function') return Promise.resolve(exists(sid))
      // the default: the upstream-stat analogue over the fixture home
      // (the canonical session log — any generation root, zstd or raw;
      // the same shapes the pre-C1 glue probe matched).
      const home = process.env.DSH_HOME
      if (home === undefined) return Promise.resolve(false)
      const sessionsRoot = join(home, 'sessions')
      let profiles
      try {
        profiles = readdirSync(sessionsRoot, { withFileTypes: true }).filter((e) => e.isDirectory())
      } catch {
        return Promise.resolve(false)
      }
      for (const pd of profiles) {
        const dir = join(sessionsRoot, pd.name, sid)
        let entries
        try {
          entries = readdirSync(dir, { withFileTypes: true })
        } catch {
          continue
        }
        if (entries.some((e) => e.isFile() && /^session(\.v\d+)?\.jsonl(\.zstd)?$/.test(e.name))) {
          return Promise.resolve(true)
        }
      }
      return Promise.resolve(false)
    },
  }
}

/**
 * The opened-TeamDomain double: the repository lists the glue reads
 * (memberInstances + overrides + teamSessions, T12-M2) plus the REAL
 * durable-consumption resolvers (the glue's consumption boundary stays the
 * production code path).
 *
 * @param {object} [params]
 * @param {object[]} [params.members] memberInstance rows of the DEFAULT
 *   root (childSessionId/instanceId)
 * @param {Object<string, object[]>} [params.membersByRoot] TCM-D4: per-root
 *   memberInstance rows for NON-default roots (a key present with an empty
 *   array says "this root has no members"; an absent key falls back to
 *   `members`, preserving the pre-TCM-D4 behavior)
 * @param {object[]} [params.overrides] governance override records of the
 *   DEFAULT root
 * @param {Object<string, object[]>} [params.overridesByRoot] TCM-D4: per-root
 *   governance override rows for NON-default roots (same fallback semantics
 *   as membersByRoot)
 * @param {object} [params.teamSession] the durable TeamSession row of the
 *   DEFAULT root (T12-M2: exposed as repositories.teamSessions — the
 *   persona step record for the root)
 * @param {object[]} [params.teamSessions] TCM-D4: the durable TeamSession
 *   rows of EVERY team root of the world (a multi-root domain — a freshly
 *   created team is a team root of the same row; `teamSession` is appended
 *   as the default root's row when both are given). `get(id)` resolves by
 *   the row's rootSessionId (the pre-TCM-D4 double returned the default
 *   row for EVERY id — a single-root world cannot observe the difference).
 */
export async function createDomainDouble({
  members = [],
  membersByRoot = {},
  overrides = [],
  overridesByRoot = {},
  teamSession = undefined,
  teamSessions = [],
} = {}) {
  const [modelModule, capabilityModule] = await Promise.all([
    import('../agent-setup/model/index.js'),
    import('../agent-setup/capability/index.js'),
  ])
  const rows = teamSession === undefined ? [...teamSessions] : [...teamSessions, teamSession]
  const findRow = (id) => rows.find((row) => String(row.rootSessionId) === String(id))
  const pickByRoot = (byRoot, root, fallback) =>
    Object.prototype.hasOwnProperty.call(byRoot, String(root)) ? byRoot[String(root)] : fallback
  return {
    repositories: {
      memberInstances: { list: (root) => pickByRoot(membersByRoot, root, members) },
      overrides: { list: (root) => pickByRoot(overridesByRoot, root, overrides) },
      teamSessions: { get: (id) => findRow(id), list: () => rows },
    },
    consumption: {
      model: { resolveDurableModelSelection: modelModule.resolveDurableModelSelection },
      capability: { resolveDurableMcpFacet: capabilityModule.resolveDurableMcpFacet },
    },
  }
}

/**
 * The subagents service double (the SubagentRuntime surface drainDescendants
 * consumes): records every drain/list call; configurable rejection of the
 * drain (the real service rejects with an aggregate after all branches
 * settle when any failed) and a configurable descendant tree.
 *
 * @param {object} [options]
 * @param {'reject'} [options.drainBehavior] reject the drain call
 * @param {string} [options.drainErrorMessage]
 * @param {object[]} [options.descendants] listDescendants result entries
 */
export function createSubagentsDouble(options = {}) {
  const drainCalls = []
  const listCalls = []
  const descendants = options.descendants ?? []
  return {
    drainCalls,
    listCalls,
    drainContinuableDescendants(parents) {
      drainCalls.push(parents)
      if (options.drainBehavior === 'reject') {
        return Promise.reject(new Error(options.drainErrorMessage ?? 'subagent drain failed (aggregate)'))
      }
      return Promise.resolve()
    },
    listDescendants(rootSessionId) {
      listCalls.push(rootSessionId)
      return Promise.resolve(descendants)
    },
  }
}

/**
 * The agentPresets service double (the DSH AgentPresets public service —
 * the ordinary-preset base-tool substrate for the team-CREATED agents,
 * D1 v2 → v3: member agents (v2) AND the root agent (v3)):
 * records every `mount(agentCtx, presetId)` call (`presetId` undefined =
 * the deployment default the service resolves itself); a configurable
 * rejection (the real service rejects on an unknown preset id).
 *
 * @param {object} [options]
 * @param {'reject'} [options.mountBehavior] reject the mount call
 * @param {string} [options.mountErrorMessage]
 */
export function createAgentPresetsDouble(options = {}) {
  const mounts = []
  return {
    mounts,
    mount(agentCtx, presetId) {
      mounts.push({ agentCtx, presetId })
      if (options.mountBehavior === 'reject') {
        return Promise.reject(new Error(options.mountErrorMessage ?? 'agent presets mount failed'))
      }
      return Promise.resolve({ presetId: presetId ?? 'default' })
    },
  }
}

/**
 * Invoke the REAL `system-prompt/assemble` waterfall listener the glue's
 * agentSetup registered through installModelSelection (the public DSH
 * seam), with next() returning the minimal assembled payload. The result
 * IS the actual agent boundary: when a selection is installed the returned
 * variables carry its provider/model; when none may be selected the
 * assembled payload passes through untouched (no provider/model).
 *
 * @param {object} agentCtx - the agent-scoped ctx of a settled handle.
 * @returns {Promise<object|undefined>} the assembled payload (undefined
 *   when no model-selection listener is installed).
 */
export async function observeAssembly(agentCtx) {
  const entry = agentCtx.listeners.find((l) => l.event === 'system-prompt/assemble' && l.active)
  if (entry === undefined) return undefined
  return entry.listener(null, null, async () => ({ variables: {} }))
}

/**
 * The full live-binding test world: the real glue over the doubles.
 *
 * @param {object} [options]
 * @param {string} [options.rootSessionId]
 * @param {object[]} [options.members] domain memberInstance rows of the
 *   world's default (boot) root
 * @param {Object<string, object[]>} [options.membersByRoot] TCM-D4: per-root
 *   member rows for non-boot roots (see createDomainDouble)
 * @param {object[]} [options.overrides] domain governance override records
 *   of the world's default (boot) root
 * @param {Object<string, object[]>} [options.overridesByRoot] TCM-D4: per-root
 *   override rows for non-boot roots (see createDomainDouble)
 * @param {object} [options.teamSession] the durable TeamSession row of the
 *   world's default (boot) root (T12-M2)
 * @param {object[]} [options.teamSessions] TCM-D4: the durable TeamSession
 *   rows of every team root of the world (multi-root domain)
 * @param {Array<{name: string, order: number, text: string}>} [options.systemPromptGlobals]
 *   the world's global prompt layer (T12-M2; default: harness:identity +
 *   a global deployment:persona with empty text)
 * @param {object} [options.configOverrides] extra TeamPluginConfig fields
 *   (bootPhase, seedMembers, mcpServer, externalPolicyFacts, ...)
 * @param {object} [options.teamTools] the tool stack (teamToolsRef.current)
 * @param {object} [options.agents] extra agents-double options (whenIdleBehavior)
 * @param {Record<string, string>} [options.mcpFailures] multi-mcp (Task C,
 *   plan §6.7): per-server MCP activation failure injection — a recorded
 *   plugin fiber whose `options.serverName` has an entry here REJECTS on
 *   await with `new Error(<message>)` (the real mcpClient fiber's
 *   failOnStartupError rejection). Passed through to the agents double.
 * @param {Record<string, string[]>} [options.mcpToolNames] multi-mcp (Task
 *   C, plan §6.11): per-server MCP tool names — registered on the agent
 *   ctx through the real `tools.register` path at the fiber's activation
 *   (the Permission Coverage Gate's proven-mount delta basis). Passed
 *   through to the agents double.
 * @param {object} [options.subagents] the subagents service double (absent = the
 *   production host seam not wired: drain is typed fail-closed)
 * @param {object|null} [options.agentPresets] the agentPresets service
 *   double (D1 v2 → v3: the ordinary-preset base-tool substrate the
 *   MEMBER agents (v2) AND the ROOT agent (v3) mount). UNDEFINED (the
 *   default) = a RECORDING double the bridge supplies (the v3 root mount
 *   runs in every world; the returned world.agentPresets is that double).
 *   NULL = the glue dep is omitted entirely (the production host seam not
 *   wired: the first setup fails closed with the typed
 *   member-base-tools-unavailable error).
 * @param {object} [options.controlServiceRef] the shared control-service
 *   reference (alpha.2 A6, the teamToolsRef pattern): the caller-owned
 *   `{ current }` object the glue reads LAZILY in agentSetup for
 *   `capabilities.permissions` templates. The world returns the SAME
 *   object (world.controlServiceRef) so a test can fill `.current` after
 *   construction and before boot to pin the lazy read. Absent = the glue
 *   dep is not passed (alpha.1/legacy worlds never read it; a
 *   permissions-carrying template then fails closed with the typed
 *   alpha2-permission-control-unavailable error).
 * @param {Array<{blueprintId: string, revision: string, source: string}>}
 *   [options.blueprintSources] BP-F (issue #2 blueprint-loading, plan
 *   §11.1): the world's blueprint store — the saved-source stand-in the
 *   DEFAULT per-root resolver strong-parses (a TeamSession row's bound
 *   snapshot ref must name an entry here; the parse's contentHash is
 *   verified against the ref — strict, like the host resolver). Absent =
 *   an empty store (a row bound to a non-anchor snapshot fails closed).
 * @param {(teamRootSid: string) => (object|null)} [options.resolveBoundBlueprint]
 *   BP-F: an OVERRIDE per-root bound-blueprint resolver passed straight
 *   through to the glue (e.g. a production-shaped live-authority
 *   resolver). Absent = the bridge's default strict map resolver over
 *   `options.blueprintSources` + the row-anchor fallback (a row without a
 *   bound snapshot ref resolves the row anchor, exactly like the host).
 * @param {import('../src/plugin/team-session-activation.js').TeamSessionActivationFence} [options.activationFence]
 *   C1 (restart-recovery, guide §4.3/§13.3): the activation fence the
 *   world wires — auto-wired into the fake `agent/created` (AWAITED veto)
 *   + `agent/disposed` (exact-generation barrier) listeners and passed to
 *   the glue exactly like the production host. Typed with the REAL fence
 *   interface (the structural inference from the old usage sites went
 *   stale when the supplement round reworked the recovery signature —
 *   `recoverWriterConflict` now takes `{ afterEpoch, deadlineMs }`),
 *   so a world passing a real fence is checked against the true
 *   surface. Absent = a pre-C1 world (no listeners, no fence dep).
 * @returns {Promise<object>} the world (binding + records + doubles).
 */
export async function createLiveWorld(options = {}) {
  const glue = await loadGlueModule()
  const rootSessionId = options.rootSessionId ?? 'session-t12a-root'
  // C1 (restart-recovery, guide §13.3): the auto-wired fake agent/created
  // + agent/disposed events — the bridge plays the HOST stand-in, so when
  // a fence is supplied it wires the SAME two listeners the production
  // host registers at the top of apply(): created → the AWAITED veto
  // (fence.beforeAgentCreated — a rejection rejects the activation),
  // disposed → the exact-generation barrier (fence.onAgentDisposed,
  // fire-and-forget). A test-provided options.agents.activationEvents
  // (or options.activationEvents) wins over the auto-wire.
  const autoActivationEvents =
    options.activationFence !== undefined
      ? (event) => {
          if (event.kind === 'created') {
            return options.activationFence.beforeAgentCreated({
              agent: event.agent,
              source: event.source,
            })
          }
          options.activationFence.onAgentDisposed(event.agent)
        }
      : undefined
  const activationEvents =
    options.activationEvents ??
    (options.agents !== undefined && options.agents.activationEvents !== undefined
      ? options.agents.activationEvents
      : autoActivationEvents)
  // S1 (supplement INV-3): a world that FIRES `agent/created` models the
  // 0.1.7 host — and the 0.1.7 factory's `AgentSetup` contract is the
  // EXPLICIT-agent call (`setup(agentCtx, agent)` — the Commit-4 in-host
  // evidence: setup receives the very Agent object the awaited-serial
  // announce later carries). The fence's exact-generation claim keys on
  // that object, so fired-event worlds run explicit-agent mode unless
  // the caller opts out (the one-arg 0.1.2-era contract is only modeled
  // by event-less worlds — the alpha2 compat matrix).
  const firedEventsExplicitAgent =
    activationEvents !== undefined &&
    (options.agents === undefined || options.agents.passExplicitAgent === undefined)
  const agents = createAgentsDouble({
    ...(activationEvents !== undefined ? { activationEvents } : {}),
    ...(options.agents ?? {}),
    ...(firedEventsExplicitAgent ? { passExplicitAgent: true } : {}),
    systemPromptGlobals: options.systemPromptGlobals,
    // multi-mcp (Task C): the per-server activation behavior tables
    // (plan §6.7 failure injection / §6.11 coverage tool names) — passed
    // through to the agents double verbatim (absent = pre-multi-mcp).
    mcpFailures: options.mcpFailures,
    mcpToolNames: options.mcpToolNames,
  })
  // C1 (guide §5.1/§13.2): the sessionPersistence double serves `exists`
  // (the glue's durable-existence seam) — default = the fixture-home
  // analogue of the upstream stat() truth; options.persistence overrides
  // (a throwing exists models the D4 backend fault).
  const sessionPersistence = createSessionPersistenceDouble(options.persistence ?? {})
  const domain = await createDomainDouble({
    members: options.members ?? [],
    membersByRoot: options.membersByRoot ?? {},
    overrides: options.overrides ?? [],
    overridesByRoot: options.overridesByRoot ?? {},
    teamSessions: options.teamSessions,
    // The default root's row is synthesized only when the caller did not
    // supply the row list at all (a multi-root list is assumed to carry
    // the default root's own row — no duplicate at one key).
    teamSession:
      options.teamSession ??
      (options.teamSessions === undefined
        ? { rootSessionId, sessionId: rootSessionId, blueprintId: 'team.t12a', generation: 1 }
        : undefined),
  })
  const config = {
    bootPhase: 'create',
    rootSessionId,
    // T12-M2: a VALID closed-v1 blueprint document (the persona glue parses
    // it lazily — the previous malformed 'team: {}' default broke the
    // parse). The default carries distinct leader/member personas so the
    // persona assertions have stable text to expect.
    blueprintSource: [
      '---',
      'schemaVersion: 1',
      'blueprintId: team.t12a',
      'revision: "1"',
      'leader:',
      '  templateId: leader',
      '  persona: "You are the leader of the t12a test team."',
      'members:',
      '  - templateId: tpl-t12a',
      '    persona: "You are member tpl-t12a of the t12a test team."',
      '  - templateId: t12a-worker',
      '    persona: "You are member t12a-worker of the t12a test team."',
      'requirements: []',
      'memberEnvelopes: []',
      'policyStates: []',
      'metadata: {}',
      '---',
      '',
    ].join('\n'),
    generation: 1,
    defaultWorkspace: join(WORKTREE_ROOT, 'default-workspace'),
    seedMembers: [],
    staticModel: { provider: 't12a-baseline', model: 't12a-baseline-model' },
    deniedSelection: { provider: 't12a-denied', model: 't12a-denied-model' },
    mcpServer: { name: 't12a-mini-mcp', port: 3999 },
    environmentFacts: [],
    externalPolicyFacts: { hard: {}, capabilityExists: {} },
    glueUrl: new URL('../src/plugin/live/agent-bindings.mjs', import.meta.url).href,
    ...options.configOverrides,
  }
  const teamToolsRef = { current: options.teamTools !== undefined ? options.teamTools : undefined }
  // alpha.2 (A6): the shared control-service reference (the teamToolsRef
  // pattern — the caller owns the object; the world returns the SAME
  // object so a test can fill `.current` after construction and before
  // boot to pin the glue's LAZY read). Absent = the glue dep is not
  // passed at all (the legacy/alpha.1 worlds never read it).
  const controlServiceRef =
    options.controlServiceRef !== undefined ? options.controlServiceRef : undefined
  // D1 (v3): the agentPresets service double — the ordinary-preset base-tool
  // substrate the team-CREATED agents mount: the MEMBER agents (v2) AND the
  // ROOT agent (v3). DEFAULT (options.agentPresets === undefined) = a
  // RECORDING double: the v3 root mount runs in EVERY world, so a world
  // without the service at all would fail closed at the root creation.
  // options.agentPresets === null OMITS the glue dep entirely (the
  // production host seam not wired — the typed fail-closed leg).
  const agentPresetsDouble =
    options.agentPresets === undefined ? createAgentPresetsDouble() : options.agentPresets
  const now = () => '2026-08-31T00:00:00.000Z'
  const binding = glue.createAgentBindings({
    agents,
    sessionPersistence,
    domain,
    config,
    teamToolsRef,
    controlServiceRef,
    now,
    ...(options.subagents !== undefined ? { subagents: options.subagents } : {}),
    ...(agentPresetsDouble !== null && agentPresetsDouble !== undefined
      ? { agentPresets: agentPresetsDouble }
      : {}),
    // alpha.2 (A6, V1-1): the per-agent fs seam accessor — routes to each
    // agent ctx double's OWN fake fs (makeAgentCtx attaches makeFakeFs()),
    // so per-agent call-record assertions keep working (a6a's
    // memberCtx.fs.calls / leaderCtx.fs.calls). options.fsBackend overrides
    // it (the resolve-time fail-closed leg); options.fsBackend = null OMITS
    // the dep entirely (the install-time fail-closed leg).
    ...(options.fsBackend === null
      ? {}
      : { fsBackend: options.fsBackend ?? ((agentCtx) => agentCtx.fs) }),
    // BP-F (issue #2 blueprint-loading, plan §11.1): the per-Team bound-
    // blueprint resolver — the bridge plays the HOST stand-in, so it
    // ALWAYS injects one (the production host does too): a caller may
    // override with options.resolveBoundBlueprint (a production-shaped
    // authority resolver); the default is a strict map resolver over
    // options.blueprintSources — the row's bound snapshot ref must name a
    // store entry, and the parse's contentHash is verified against the
    // ref (hash equality, the plan §11.1 chain). A row WITHOUT a bound
    // snapshot ref (a pre-repair row) falls back to the row anchor,
    // exactly like the host resolver.
    resolveBoundBlueprint:
      options.resolveBoundBlueprint ??
      ((teamRootSid) => {
        const row = domain.repositories.teamSessions.get(String(teamRootSid))
        if (row === undefined) {
          throw new Error(
            `t12a bridge: resolveBoundBlueprint('${teamRootSid}'): the domain carries no durable TeamSession row for this root (strict, like the host resolver)`,
          )
        }
        const ref = row.blueprint
        if (ref === undefined) {
          return parseBlueprint(String(config.blueprintSource ?? ''))
        }
        const entry = (options.blueprintSources ?? []).find(
          (e) => e.blueprintId === ref.blueprintId && e.revision === ref.revision,
        )
        if (entry === undefined) {
          throw new Error(
            `t12a bridge: resolveBoundBlueprint('${teamRootSid}'): no blueprint source for the bound snapshot ${ref.blueprintId}@${ref.revision} (pass options.blueprintSources)`,
          )
        }
        const parsed = parseBlueprint(entry.source)
        if (parsed.contentHash !== ref.contentHash) {
          throw new Error(
            `t12a bridge: resolveBoundBlueprint('${teamRootSid}'): hash mismatch — the bound snapshot ref carries ${ref.contentHash} but the source parses to ${parsed.contentHash} (strict, like the host resolver)`,
          )
        }
        return parsed
      }),
    // C1 (restart-recovery, guide §4.3/§13.3): the activation fence dep
    // (absent = the pre-C1 glue fallback: the wrappers run the operation
    // direct; the ensureLiveAgent rollback / writer-conflict waits are
    // skipped — so no pre-C1 test world breaks wholesale).
    ...(options.activationFence !== undefined ? { activationFence: options.activationFence } : {}),
    // C1 (guide §7.2): the bounded writer-conflict recovery window
    // (tiny for the G5/G6 determinism; absent = the glue default 10 s).
    ...(options.writerHandoffTimeoutMs !== undefined
      ? { writerHandoffTimeoutMs: options.writerHandoffTimeoutMs }
      : {}),
  })
  return {
    rootSessionId,
    config,
    binding,
    agents,
    sessionPersistence,
    domain,
    teamToolsRef,
    controlServiceRef,
    subagents: options.subagents,
    agentPresets: agentPresetsDouble,
    // C1 (guide §13.3): the fence the world wired (undefined = pre-C1
    // world) — a test asserts its state (records, permits) through it.
    activationFence: options.activationFence,
    records: {
      creates: agents.creates,
      resumes: agents.resumes,
      disposals: agents.disposals,
      followups: agents.followups,
      steers: agents.steers,
      injects: agents.injects,
      cancels: agents.cancels,
      materialized: sessionPersistence.materialized,
    },
  }
}

/**
 * Run `fn` with DSH_HOME pointed at `home` (restore the previous value —
 * including absent — afterwards, AFTER `fn` settles, so an async `fn` sees
 * the home for its whole lifetime). C1 (guide §5): the glue NO LONGER
 * reads process.env.DSH_HOME (the physical probe is deleted); the home
 * now feeds the sessionPersistence double's DEFAULT `exists` (the
 * fixture-home analogue of the upstream stat() truth — see
 * createSessionPersistenceDouble). Tests that need durable sessions set
 * the home + writeDurableFixture, snapshot the recorded state, and let
 * this restore it BEFORE any later file's setup runs.
 */
export async function withDshHome(home, fn) {
  const previous = process.env.DSH_HOME
  process.env.DSH_HOME = home
  try {
    return await fn()
  } finally {
    if (previous === undefined) delete process.env.DSH_HOME
    else process.env.DSH_HOME = previous
  }
}

/**
 * Write an empty durable-session fixture (`session.jsonl.zstd`) under
 * `<home>/sessions/<profile>/<sessionId>/` so the glue's sessionIsDurable
 * check sees the session as durable. The fixture must live INSIDE the
 * worktree (the workspace-write sandbox); remove it with
 * removeFixtureHome before the test file's setup completes (git status
 * must stay clean).
 *
 * @param {string} home the fake DSH_HOME root
 * @param {string} sessionId the session id the fixture stands for
 * @param {string} [profile] the profile dir name (any non-empty name)
 * @returns {string} the fixture home root (for cleanup).
 */
export function writeDurableFixture(home, sessionId, profile = 'test-profile', logFile = 'session.jsonl.zstd') {
  const dir = join(home, 'sessions', profile, sessionId)
  mkdirSync(dir, { recursive: true })
  writeFileSync(join(dir, logFile), '', 'utf8')
  return home
}

/** Remove a whole fixture home tree (idempotent). */
export function removeFixtureHome(home) {
  rmSync(home, { recursive: true, force: true })
}

/**
 * team-session-durability.test.ts — C1 (restart-recovery 0.1.7-rc.1,
 * guide §13.2): the DURABILITY SEAM unit tests (D1–D4). The pre-C1
 * glue read `<DSH_HOME>/sessions/<profile>/<sessionId>/` on disk
 * (the `sessionIsDurable` physical layout probe — env-dependent,
 * backend-layout-dependent, blind to the backend's own view). C1
 * deletes that probe from the production glue: the cold-resume
 * eligibility is now the PUBLIC session-persistence seam
 * (`sessionPersistence.exists` — the host wrapper's
 * `stat(id) !== undefined`, guide §5.1/§5.2).
 *
 * Cases (guide §13.2, verbatim):
 *  - D1 `DSH_HOME` completely UNSET + `exists()` returns true →
 *    `ensureLiveAgent` RESUMES — the cold-resume eligibility may no
 *    longer be false because of the environment variable;
 *  - D2 the test provides NO filesystem tree at all (the V4 filename
 *    is completely invisible; an empty home with no `sessions/`
 *    subtree) + `exists = true` → the resume SUCCEEDS (the backend
 *    seam is the single authority, the layout is invisible);
 *  - D3 `exists = false` → the EXISTING `p6t6: ... neither live nor
 *    durable` error is preserved (the S6 mapping onto
 *    NO_DURABLE_ARTIFACT is pinned by the d2-s6 ensureRootLive suite);
 *  - D4 the persistence seam FAULTS (`stat` throws) → the fault
 *    PROPAGATES unchanged — it must never be misread as "not durable"
 *    (a backend fault masquerading as a nonexistent session is the
 *    exact failure class the seam exists to eliminate).
 *
 * World shape: `createLiveWorld` WITHOUT a boot (the root session is
 * not live — the ensureLiveAgent RESUME path is the one under test);
 * the sessionPersistence double's `exists` is overridden per case
 * (the bridge's default — the fixture-home analogue of the upstream
 * stat() truth — is intentionally bypassed: these cases test the seam
 * CONTRACT, not the fixture model).
 *
 * @module @dsh-agent-team/runtime/test/team-session-durability
 */

import { describe, expect, it } from 'vitest'

import {
  createLiveWorld,
  WORKTREE_ROOT,
} from './t12a-live-bridge.mjs'

const HOME = `${WORKTREE_ROOT}/.tmp-team-c1-home`

async function captureReject(fn: () => Promise<unknown>): Promise<unknown> {
  try {
    await fn()
    throw new Error('D-test guard: expected the call to reject')
  } catch (error) {
    if (error instanceof Error && error.message === 'D-test guard: expected the call to reject') {
      throw error
    }
    return error
  }
}

/** Drive one case: a world without a boot + ensureLiveAgent on the root. */
async function driveCase(exists: (sessionId: string) => boolean | Promise<boolean> | never): Promise<{
  resumed: readonly string[]
  created: readonly string[]
  rejection: unknown
}> {
  const world = await createLiveWorld({
    rootSessionId: 'session-team-c1-durability',
    persistence: { exists },
  })
  let rejection: unknown
  try {
    await world.binding.ensureLiveAgent('session-team-c1-durability')
  } catch (error) {
    rejection = error
  }
  await world.binding.close().catch(() => undefined)
  return {
    resumed: world.agents.resumes.map((r) => r.sessionId),
    created: world.agents.creates.map((c) => c.sessionId),
    rejection,
  }
}

const DSH_HOME_KEY = 'DSH_HOME'

// The runtime package's minimal ambient Node shim (src/plugin/
// node-min.d.ts) declares only what the PRODUCTION code reads
// (process.cwd — the pre-C1 sessionIsDurable's process.env.DSH_HOME read
// is deleted, so `env` is not part of the shim). This test drives the
// environment variable directly, so it casts the process global once.
const processEnv = (process as unknown as { env: Record<string, string | undefined> }).env

const D = await (async () => {
  const previousHome = processEnv[DSH_HOME_KEY]
  try {
    // D1 — DSH_HOME completely UNSET: the eligibility comes from the
    // seam, not the environment.
    delete processEnv[DSH_HOME_KEY]
    const d1 = await driveCase(() => true)

    // D2 — NO filesystem tree at all: DSH_HOME points at a home directory
    // with no sessions/ subtree whatsoever (even a V4-era filename would
    // be invisible under it) — and the seam alone decides.
    const { mkdirSync, rmSync } = await import('node:fs')
    mkdirSync(HOME, { recursive: true })
    processEnv[DSH_HOME_KEY] = HOME
    const d2 = await driveCase(() => true)
    rmSync(HOME, { recursive: true, force: true })

    // D3 — nonexistent: the existing "neither live nor durable" error.
    const d3 = await driveCase(() => false)

    // D4 — the persistence seam FAULTS: the fault propagates verbatim.
    const fault = new Error('backend stat fault: the durable backend is unreachable')
    const d4 = await driveCase(() => {
      throw fault
    })

    return {
      d1,
      d2,
      d3,
      d4,
      d4Fault: fault,
    }
  } finally {
    if (previousHome === undefined) delete processEnv[DSH_HOME_KEY]
    else processEnv[DSH_HOME_KEY] = previousHome
  }
})()

describe('C1 (guide §13.2): the durability seam (sessionPersistence.exists)', () => {
  it('D1 DSH_HOME completely unset + exists() = true: ensureLiveAgent RESUMES (no env-var false)', () => {
    expect(D.d1.rejection).toBeUndefined()
    expect(D.d1.resumed).toEqual(['session-team-c1-durability'])
    expect(D.d1.created).toEqual([])
  })

  it('D2 no filesystem tree at all + exists = true: the resume SUCCEEDS (the layout is invisible)', () => {
    expect(D.d2.rejection).toBeUndefined()
    expect(D.d2.resumed).toEqual(['session-team-c1-durability'])
    expect(D.d2.created).toEqual([])
  })

  it('D3 exists = false: the EXISTING "neither live nor durable" error is preserved (no resume)', () => {
    expect(D.d3.resumed).toEqual([])
    expect(D.d3.created).toEqual([])
    const rejection = D.d3.rejection
    expect(rejection instanceof Error).toBe(true)
    if (rejection instanceof Error) {
      expect(rejection.message).toBe(
        `p6t6: session 'session-team-c1-durability' is neither live nor durable — no agent to execute a tool on`,
      )
    }
  })

  it('D4 the persistence seam faults: the fault PROPAGATES (never misread as "not durable")', () => {
    expect(D.d4.resumed).toEqual([])
    expect(D.d4.created).toEqual([])
    // the EXACT fault object propagates (not a re-wrapped "not durable").
    expect(D.d4.rejection).toBe(D.d4Fault)
  })
})

/**
 * H1/H2 (supplement guide §4.3) — the production host STARTUP race:
 * the activation listeners are registered at the TOP of `apply()`, but
 * the ownership resolver binds only AFTER the domain open — the window
 * in which a real host's browser-style activation arrives before any
 * Team classification is possible (INV-4: classification PENDING, never
 * "unmanaged"):
 *
 *   H1 — foreign TEAM activation (an `agent/created` of a Team-managed
 *        session that arrived WITHOUT the Team glue — no ownership
 *        guard, no exact claim — e.g. the browser opening the team
 *        session's page while the row's domain open is still pending):
 *        it must NOT PASS during the window (the fence suspends the
 *        awaited listener — no early pass, no early veto). Once the
 *        domain opens and the resolver binds → VETO (the typed
 *        TeamSessionActivationInterceptedError).
 *   H2 — the same startup window, an ORDINARY session (unmanaged): the
 *        activation likewise suspends (no early pass), and after the
 *        resolver bind it classifies unmanaged → PASS (the ordinary
 *        open proceeds upstream-equivalently).
 *
 * S1–S5 (PR #31 minimal supplement — startup-failure isolation): the
 * bootstrap rejects BEFORE the resolver binds (the domain open itself
 * fails): without isolation, every later ordinary `agent/created` (the
 * fence listeners are registered `{ global: true }` at the top of
 * `apply()`) would await the `ownershipReady` barrier forever on a row
 * that keeps running (a failed boot is terminal, but the row stops only
 * on its own teardown). The host now closes its fence on the bootstrap
 * rejection:
 *   S1 — the fence listener is registered (apply top) and the resolver
 *        is unbound when the bootstrap fails before the domain open
 *        settles;
 *   S2 — an ordinary `agent/created` suspended in the window SETTLES
 *        (pass-through) after the bootstrap failure — no permanent hang
 *        on `ownershipReady`;
 *   S3 — a NEW ordinary activation after the failure passes through
 *        immediately (the failed row no longer blocks ordinary
 *        non-Team sessions);
 *   S4 — the normal successful bootstrap path is unchanged (the
 *        successful world still vetoes the foreign Team activation and
 *        passes the ordinary one — the fence stays armed, not closed);
 *   S5 — the row-stop backstop's `close()` after the bootstrap-failure
 *        close is exception-free (idempotent double close).
 *
 * World shape (the production restart cycle over ONE medium, the
 * p8s7r4 / t12b1 / rmr-create-or-open pattern over a REAL file storage
 * seam):
 *   phase 1 — a full production `create` (ungated): mints the durable
 *             TeamSession for the root.
 *   phase 2 — a production `create-or-open` RESTART whose seam `open`
 *             is GATED (the domain open — and therefore the
 *             `bindOwnershipResolver` right after it — is deferred
 *             behind the test's release). The `apply` call is NOT
 *             awaited; its synchronous prefix has already registered
 *             the activation listeners (verified before driving).
 *
 * Runner note: the plain-node vitest shim forbids async `it()` bodies —
 * the scenario runs at module load (top-level await), the `it` bodies
 * assert synchronously (the p8s7r4 pattern).
 * @module @dsh-agent-team/runtime/test/team-session-startup-fence
 */

